**Recommendation:** Remove `eval()` entirely. If the intent is to evaluate mathematical expressions, use a sandboxed expression parser like `mathjs` or `expr-eval`. If the intent is dynamic logic, redesign the feature to avoid arbitrary code execution.

```typescript
import { evaluate } from 'mathjs';

export function processRequest(req: Request, res: Response): number {
  const expression = req.body.expression;
  if (typeof expression !== 'string' || expression.length > 256) {
    throw new Error('Invalid expression');
  }
  return evaluate(expression); // sandboxed math evaluation
}
```

