  ```typescript
  import path from "path";

  const SAFE_ROOT = path.resolve(__dirname, "public");

  app.get("/api/file", (req, res) => {
    const filePath = req.query.path as string;
    if (!filePath) return res.status(400).send("Missing path");
    const resolved = path.resolve(SAFE_ROOT, filePath);
    if (!resolved.startsWith(SAFE_ROOT)) {
      return res.status(403).send("Forbidden");
    }
    res.sendFile(resolved);
  });
  ```
- **Reference:** [Express res.sendFile documentation](https://expressjs.com/en/api.html#res.sendFile)

